mapper.select:
SELECT sc_id, sc_dv_id, sc_serial_number, sc_start_date, sc_end_date, sc_duration, sc_status, sc_direction, sc_audio_path, sc_has_audio, sc_reg_date FROM tbl_sip_call
ORDER BY sc_reg_date DESC, sc_id DESC
LIMIT #{listSize}
OFFSET #{offset}

SELECT rn FROM (
	SELECT sc_id, ROW_NUMBER() OVER (ORDER BY sc_reg_date DESC, sc_id DESC) AS rn
	FROM tbl_sip_call

) ranked
WHERE sc_id = #{focusScId}
